package br.com.luis.cursos.controller;
import br.com.luis.cursos.model.Curso; import br.com.luis.cursos.repository.*; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/cursos") public class CursoController{ private final CursoRepository repo; private final InstrutorRepository instrutores; public CursoController(CursoRepository repo,InstrutorRepository instrutores){this.repo=repo;this.instrutores=instrutores;} @GetMapping public List<Curso> listar(){return repo.findAll();} @GetMapping("/ativos") public List<Curso> ativos(){return repo.findByAtivoTrue();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Curso criar(@Valid @RequestBody Curso c){if(c.getInstrutor()==null||c.getInstrutor().getId()==null) throw new IllegalArgumentException("instrutor é obrigatório"); c.setInstrutor(instrutores.findById(c.getInstrutor().getId()).orElseThrow()); return repo.save(c);} @PatchMapping("/{id}/status") public Curso status(@PathVariable Long id,@RequestParam boolean ativo){Curso c=repo.findById(id).orElseThrow(); c.setAtivo(ativo); return repo.save(c);} }
